-- Maternity Follow-Up Tracker
-- MySQL schema generated from current Django models.
--

CREATE DATABASE IF NOT EXISTS maternity_db
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE maternity_db;

SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET foreign_key_checks = 0;

CREATE TABLE `django_admin_log` (`id` integer AUTO_INCREMENT NOT NULL PRIMARY KEY, `action_time` datetime(6) NOT NULL, `user_id` char(32) NOT NULL, `content_type_id` integer NULL, `object_id` longtext NULL, `object_repr` varchar(200) NOT NULL, `action_flag` smallint UNSIGNED NOT NULL CHECK (`action_flag` >= 0), `change_message` longtext NOT NULL);
